+++ b/src/paginate.ts
@@ -1,10 +1,27 @@
 import type { Breed } from './types'

+const PAGE_SIZE = 20
+
+export function page<T>(items: T[], pageNumber: number): T[] {
+  const from = pageNumber * PAGE_SIZE
+
+  return items.slice(from, from + PAGE_SIZE)
+}
+
+export function pageCount(total: number): number {
+  return Math.max(1, Math.ceil(total / PAGE_SIZE))
+}
+
+export function breedsPage(all: Breed[], pageNumber: number) {
+  return {
+    items: page(all, pageNumber),
+    pages: pageCount(all.length),
+    current: pageNumber,
+  }
+}
